tton type="button" class="btn btn-secondary text-xs" data-add-line>Add book</button></div><div class="space-y-2" data-transfer-lines><div class="form-grid transfer-line"><select name="items[0][book_id]" required><option value="">Select book</option>@foreach($books as $book)<option value="{{ $book->id }}">{{ $book->title }} — available: {{ $book->available_quantity }}</option>@endforeach</select><div class="flex gap-2"><input type="number" name="items[0][quantity]" min="1" required placeholder="Quantity"><button type="button" class="btn btn-secondary" data-remove-line>Remove</button></div></div></div></div></div><div class="flex justify-end border-t border-slate-200 p-5"><button class="btn btn-primary">Complete transfer</button></div></form>
<template id="transfer-line-template"><div class="form-grid transfer-line"><select required><option value="">Select book</option>@foreach($books as $book)<option value="{{ $book->id }}">{{ $book->title }} — available: {{ $book->available_quantity }}</option>@endforeach</select><div class="flex gap-2"><input type="number" min="1" required placeholder="Quantity"><button type="button" class="btn btn-secondary" data-remove-line>Remove</button></div></div></template>
<script>const kind=document.getElementById('transfer-type'),branchFields=document.querySelector('[data-branch-fields]'),userFields=document.querySelector('[data-user-fields]'),sourceUser=document.querySelector('[data-source-user]'),lines=document.querySelector('[data-transfer-lines]'),template=document.getElementById('transfer-line-template');function swap(){const type=kind.value,users=type!=='branch_to_branch';branchFields.classList.toggle('hidden',users);userFields.classList.toggle('hidden',!users);sourceUser.classList.toggle('hidden',type==='branch_to_user')}kind.addEventListener('change',swap);swap();function names(){lines.querySelectorAll('.transfer-line').forEach((line,index)=>{line.querySelector('select').name=`items[${index}][book_id]`;line.querySelector('input').name=`items[${index}][quantity]`})}document.querySelector('[data-add-line]').addEventListener('click',()=>{lines.append(template.content.cloneNode(true));names()});lines.addEventListener('click',event=>{if(event.target.matches('[data-remove-line]')&&lines.children.length>1){event.target.closest('.transfer-line').remove();names()}});</script>
